from pathlib import Path
import pandas as pd,numpy as np,json,hashlib,re,collections
H=Path(__file__).resolve().parent;R=H.parent
def norm(v):return ' '.join(str(v).casefold().replace('ё','е').replace('–','-').replace('—','-').split())
def main():
 protocol={'status':'CANDIDATES_ONLY_NO_AXIS_ADOPTION','source_snapshot':'2021-01-01T21:42:03Z','identity':'exact current source node name + exact raw addr:district and addr:region to dated census parent/region, explicit ru:formaltype; exact dated Jan2021 parent8 and NPcode official corroboration','source_places':['city','town','village','hamlet','isolated_dwelling'],'names':['name','name:ru','official_name'],'normalization':'casefold, ё→е, whitespace, Unicode dash; no administrative aliases or district→GO equivalence','uniqueness':'one census NP of ANY formaltype/name within exact parent among full roster; one sourcepoint of ANY formaltype/currentname under actual literal parent+region across all source nodes','conflicts':'any conflicting literal native11code/name/type/lifecycle => review','coordinate_measurement_date':'unknown','precision':'uncalibrated','no_centroid_no_road_selection':True}
 pp=H/'B_dated_parent_preregistration.json'
 if pp.exists():assert json.loads(pp.read_text())==protocol
 else:pp.write_text(json.dumps(protocol,ensure_ascii=False,indent=2)+'\n')
 targets=pd.read_parquet(H/'all1767_native2021_geography_gaps_source_frame.parquet');roster=pd.read_parquet(R/'data/source_controls_cycle05/latest2021_np_roster_complete_accounting.parquet');bridge=pd.read_parquet(R/'data/source_controls_cycle05/explicit2021_source_parent_bridge.parquet');gov=pd.read_csv(R/'administration2021_cycle05/sources/data-20210118-structure-20150128.csv',sep=';',encoding='cp1251',dtype=str,header=None,keep_default_na=False);gov['row1']=np.arange(1,len(gov)+1);gov['c8']=gov[0]+gov[1]+gov[2];gov['c11']=gov.c8+gov[3];nps=gov[gov[5].eq('2')&gov[3].ne('000')].set_index('c11');roles=pd.read_parquet(R/'data/source_controls_cycle05/statistical_role_primary/source_settlement_statistical_role_primary2021_v3.parquet').set_index('id');headers=gov[gov[5].isin(['1','2'])&gov[3].eq('000')]
 codeparent=dict(zip(bridge.native_np_oktmo11,bridge.native_source_parent_oktmo8));cn=collections.Counter((str(codeparent.get(str(x.native_np_oktmo11),'UNRESOLVED')),norm(x.settlement_name)) for x in roster.itertuples()); source_keys=collections.defaultdict(dict);objects={}
 for f in sorted((H/'osm2021_inventory').glob('*.parquet')):
  d=pd.read_parquet(f,filters=[('osm_type','==','node')])
  for x in d.itertuples():
   t=json.loads(x.tags_json)
   parent=t.get('addr:district');region=t.get('addr:region')
   if not parent or not region:continue
   objects[int(x.osm_id)]=x
   for name in {norm(t[k]) for k in protocol['names'] if k in t}:
    source_keys[(norm(region),norm(parent),name)][int(x.osm_id)]=x
 rows=[]
 for z in targets.itertuples():
  key=(norm(z.region_source),norm(z.mun_upper),norm(z.name));found=source_keys.get(key,{})
  for sid,x in found.items():
   t=json.loads(x.tags_json);code=str(z.native_np_oktmo11);p8=str(z.native_source_parent_oktmo8);ph=headers[headers.c8.eq(p8)];q=nps.loc[code] if code in nps.index else None;role=roles.loc[z.id] if z.id in roles.index else None;formal=t.get('official_status','');st=norm(formal).removeprefix('ru:');typeok=formal.startswith('ru:') and (st==norm(z.type) or norm(z.object_name).startswith(st+' '));nameok=q is not None and ((role is not None and bool(role.primary202101_exact_code_and_normalized_name)) or norm(q[6])==norm(z.name));pubnames=[norm(v) for v in ph[6]];exact_header=norm(z.mun_upper) in pubnames; # Section2 boilerplate alone is not alias evidence; section1 literal is required.
   dates=bool(q is not None and pd.to_datetime(q[12],dayfirst=True)<=pd.Timestamp('2021-01-01') and not ph.empty and all(pd.to_datetime(v,dayfirst=True)<=pd.Timestamp('2021-01-01') for v in ph[12]));codes={str(t[k]).strip() for k in ['ref:oktmo','oktmo:user','oktmo'] if k in t and re.fullmatch('[0-9]{11}',str(t[k]).strip())};life=any(k in t for k in ['end_date','disused:place','abandoned:place','was:place','demolished:place','removed:place','razed:place','construction:place']);reasons=[]
   for ok,reason in [(t.get('place') in protocol['source_places'],'source_not_accepted_settlement_place_class'),(cn[(p8,norm(z.name))]==1,'census_name_not_unique_across_all_formaltypes_in_parent'),(len(found)==1,'multiple_source_points_under_exact_literal_parent_region'),(typeok,'missing_or_conflicting_explicit_ru_formaltype'),(nameok,'official_Jan_NP_name_not_exact'),(exact_header,'no_literal_Jan_parent_header_equals_Oct_parent_name'),(dates,'official_effective_date_unresolved'),(code[:5]==p8[:5],'official_parent_code_scope_mismatch'),(not codes or codes=={code},'source_native11_code_conflict'),(not life,'source_lifecycle_conflict')]:
    if not ok:reasons.append(reason)
   rows.append(dict(id=z.id,name=z.name,population2021=z.population_2021,coordinate_missing=z.coordinate_missing,native_np_oktmo11=code,native_parent8=p8,source_osm_node_id=sid,source_lat=x.lat,source_lon=x.lon,source_version=x.osm_version,source_object_timestamp=x.object_timestamp,source_tags_json=x.tags_json,source_tags_sha256=x.all_source_tags_sha256,census_parent_literal=z.mun_upper,census_region_literal=z.region_source,source_parent_literal=t['addr:district'],source_region_literal=t['addr:region'],source_formal_type_literal=formal,official_Jan_NP_name=q[6] if q is not None else None,official_Jan_NP_row1=int(q.row1) if q is not None else None,official_Jan_parent_headers_json=json.dumps([{'row1':int(v.row1),'section':v[5],'raw_name':v[6],'effective_date':v[12]} for _,v in ph.iterrows()],ensure_ascii=False),all_census_NP_same_name_under_parent_count=cn[(p8,norm(z.name))],all_source_nodes_same_name_under_literal_parent_count=len(found),candidate_status='B_dated_exact_parent_candidate' if not reasons else 'B_review',unresolved_reasons_json=json.dumps(reasons),source_snapshot_utc=protocol['source_snapshot'],coordinate_measurement_date_unknown=True,coordinate_precision_unknown=True,axis_adopted=False))
 out=pd.DataFrame(rows);out.to_parquet(H/'B_dated_exact_parent_source_assertions.parquet',index=False);good=out[out.candidate_status.eq('B_dated_exact_parent_candidate')];a=pd.read_parquet(H/'dated_primary_and_geometry_validated_A_candidates_v2.parquet');aids=set(a.loc[a.candidate_status.str.startswith(('A1_validated','A2_validated')),'id']);new=good[~good.id.isin(aids)];receipt={'status':'CANDIDATE_ONLY_NO_AXIS_ADOPTION','all_source_assertions':len(out),'status_counts':out.candidate_status.value_counts().to_dict(),'unique_candidates':good.id.nunique(),'new_outside_A_candidates':new.id.nunique(),'new_missing_coord_NPs':new.loc[new.coordinate_missing,'id'].nunique(),'new_missing_population':float(new.loc[new.coordinate_missing,'population2021'].sum()),'protocol_sha256':hashlib.sha256(pp.read_bytes()).hexdigest()};(H/'B_dated_parent_receipt.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps(receipt),flush=True)
if __name__=='__main__':main()
